      "### `tunnel list`",
      "",
      "**Flags:**",
      "",
      "- `--json`",
      "",
      "**Example:**",
      "",
      "```bash",
      "omniroute tunnel list",
      "```",
      "",
      "### `tunnel create [type]`",
      "",
      "**Example:**",
